from __future__ import annotations

import json
import os
import threading
from collections.abc import Iterable
from pathlib import Path
from typing import Any

from . import format as fmt
from . import store

__all__ = [
    "ConflictError",
    "Ledger",
    "append",
    "apply_batch",
    "repair_tail",
    "snapshot",
    "verify",
]


class ConflictError(Exception):
    def __init__(
        self,
        key: str,
        incoming_rid: str,
        committed_rid: str,
        batch_index: int | None = None,
    ) -> None:
        self.key = key
        self.incoming_rid = incoming_rid
        self.committed_rid = committed_rid
        self.batch_index = batch_index
        super().__init__(
            f"conflict on key {key!r}: incoming rid {incoming_rid!r} "
            f"vs committed rid {committed_rid!r}"
            + (f" (batch_index={batch_index})" if batch_index is not None else "")
        )


_OP_PUT = "put"
_OP_DELETE = "delete"


def _normalize_op(op: Any, key: str, value: Any, rid: Any, ts: Any) -> dict[str, Any]:
    if op == _OP_PUT:
        return {"op": _OP_PUT, "key": key, "value": value, "id": rid, "ts": ts}
    if op == _OP_DELETE:
        return {"op": _OP_DELETE, "key": key, "id": rid, "ts": ts}
    raise ValueError(f"unknown op: {op!r}")


def _build_line(op_tuple: tuple) -> tuple[dict[str, Any], str]:
    op, raw_key, value, rid, ts = op_tuple
    key = fmt.normalize_key(raw_key)
    if not key:
        raise ValueError("key must be non-empty after NFC normalization")
    line = _normalize_op(op, key, value, rid, ts)
    return line, key


def _encode_line(line: dict[str, Any], prev_hash: str) -> bytes:
    completed = dict(line)
    completed["prev_hash"] = prev_hash
    completed["hash"] = ""
    completed["hash"] = fmt.line_hash(prev_hash, completed)
    payload = json.dumps(
        completed, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")
    return payload + b"\n"


def _decode_line(raw: bytes) -> dict[str, Any]:
    return json.loads(raw.decode("utf-8"))


def _committed_state(p: Path) -> tuple[dict[str, dict[str, Any]], list[bytes], str]:
    if not p.exists() or p.stat().st_size == 0:
        return {}, [], None
    raw_lines = store.read_lines(p)
    last_by_key: dict[str, dict[str, Any]] = {}
    for raw in raw_lines:
        line = _decode_line(raw)
        last_by_key[line["key"]] = line
    prev_hash = _decode_line(raw_lines[-1])["hash"]
    return last_by_key, raw_lines, prev_hash


class Ledger:
    def __init__(self, path: Path | str) -> None:
        self._path = Path(path)
        self._lock = threading.Lock()

    @property
    def path(self) -> Path:
        return self._path

    def append(self, op_tuple: tuple) -> dict[str, Any]:
        with self._lock:
            self._path.parent.mkdir(parents=True, exist_ok=True)
            line, key = _build_line(op_tuple)
            last_by_key, _raw_lines, prev_hash = _committed_state(self._path)
            committed = last_by_key.get(key)
            if committed is not None:
                if committed["id"] == line["id"]:
                    replayed = dict(committed)
                    replayed["replayed"] = True
                    replayed["committed"] = False
                    return replayed
                raise ConflictError(
                    key=key,
                    incoming_rid=line["id"],
                    committed_rid=committed["id"],
                    batch_index=None,
                )
            payload = _encode_line(
                line, prev_hash if prev_hash is not None else fmt.GENESIS
            )
            with open(self._path, "ab") as f:
                f.write(payload)
                f.flush()
                os.fsync(f.fileno())
            return _decode_line(payload[:-1])

    def verify(self) -> dict[str, Any]:
        return verify(self._path)

    def snapshot(self) -> dict[str, Any]:
        return snapshot(self._path)

    def apply_batch(self, ops: Iterable[tuple]) -> None:
        apply_batch(self._path, ops)

    def repair_tail(self) -> dict[str, Any]:
        return repair_tail(self._path)


def append(path: Path | str, op_tuple: tuple) -> dict[str, Any]:
    return Ledger(path).append(op_tuple)


def verify(path: Path | str) -> dict[str, Any]:
    p = Path(path)
    lines = store.read_lines(p)
    prev_hash = fmt.GENESIS
    for idx, raw in enumerate(lines):
        try:
            line = _decode_line(raw)
        except (UnicodeDecodeError, json.JSONDecodeError):
            return {"ok": False, "first_bad_index": idx}
        expected_hash = fmt.line_hash(prev_hash, line)
        if line.get("prev_hash") != prev_hash or line.get("hash") != expected_hash:
            return {"ok": False, "first_bad_index": idx}
        prev_hash = line["hash"]
    return {"ok": True, "first_bad_index": None}


def snapshot(path: Path | str) -> dict[str, Any]:
    p = Path(path)
    lines = store.read_lines(p)
    state: dict[str, Any] = {}
    for raw in lines:
        line = _decode_line(raw)
        op = line["op"]
        key = line["key"]
        if op == _OP_PUT:
            state[key] = line["value"]
        elif op == _OP_DELETE:
            state.pop(key, None)
    keys = sorted(state.keys())
    return {k: state[k] for k in keys}


def apply_batch(path: Path | str, ops: Iterable[tuple]) -> None:
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    last_by_key, raw_lines, prev_hash = _committed_state(p)
    state: dict[str, dict[str, Any]] = dict(last_by_key)
    new_payloads: list[bytes] = []
    if prev_hash is None:
        prev_hash = fmt.GENESIS
    op_list = list(ops)
    for idx, op_tuple in enumerate(op_list):
        line, key = _build_line(op_tuple)
        committed = state.get(key)
        if committed is not None:
            if committed["id"] != line["id"]:
                raise ConflictError(
                    key=key,
                    incoming_rid=line["id"],
                    committed_rid=committed["id"],
                    batch_index=idx,
                )
            continue
        payload = _encode_line(line, prev_hash)
        new_payloads.append(payload)
        state[key] = line
        prev_hash = _decode_line(payload[:-1])["hash"]
    if not new_payloads and not raw_lines:
        return
    final_lines: list[bytes] = []
    for raw in raw_lines:
        final_lines.append(raw + b"\n")
    final_lines.extend(new_payloads)
    store.write_atomic(p, final_lines)


def repair_tail(path: Path | str) -> dict[str, Any]:
    p = Path(path)
    verdict = verify(p)
    if verdict["ok"]:
        return {"repaired": False, "verdict": verdict}

    first_bad_index = verdict["first_bad_index"]
    raw_lines = store.read_lines(p)

    if first_bad_index is None or first_bad_index != len(raw_lines) - 1:
        return {"repaired": False, "verdict": verdict}

    last_raw = raw_lines[-1]
    try:
        _decode_line(last_raw)
    except (UnicodeDecodeError, json.JSONDecodeError):
        pass
    else:
        return {"repaired": False, "verdict": verdict}

    preserved = [raw + b"\n" for raw in raw_lines[:-1]]
    store.write_atomic(p, preserved)

    post = verify(p)
    return {"repaired": post["ok"], "verdict": post}

from __future__ import annotations

import argparse
import json
import os
import sys
from collections.abc import Sequence

from .ledger import ConflictError, Ledger

EXIT_OK = 0
EXIT_USAGE = 2
EXIT_IO = 3
EXIT_CONFLICT = 4
EXIT_CORRUPTION = 5


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="ledgerlock")
    sub = parser.add_subparsers(dest="cmd", required=True)

    p_verify = sub.add_parser("verify")
    p_verify.add_argument("path")

    p_snap = sub.add_parser("snapshot")
    p_snap.add_argument("path")
    p_snap.add_argument("--out", required=True)

    p_apply = sub.add_parser("apply")
    p_apply.add_argument("path")
    p_apply.add_argument("--batch", required=True)

    p_repair = sub.add_parser("repair-tail")
    p_repair.add_argument("path")

    return parser


def _parse_batch(path: str) -> list[tuple]:
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, list):
        raise TypeError("batch file must contain a JSON array of tuples")
    ops: list[tuple] = []
    for element in data:
        if not isinstance(element, list):
            raise TypeError("batch element must be an array")
        if len(element) != 5:
            raise ValueError("batch element must have exactly 5 fields")
        op, key, value, rid, ts = element
        ops.append((op, key, value, rid, ts))
    return ops


def _do_verify(args: argparse.Namespace) -> int:
    led = Ledger(args.path)
    verdict = led.verify()
    if verdict["ok"]:
        sys.stderr.write("verify ok\n")
        sys.stderr.flush()
        return EXIT_OK
    return EXIT_CORRUPTION


def _do_snapshot(args: argparse.Namespace) -> int:
    led = Ledger(args.path)
    state = led.snapshot()
    payload = (
        json.dumps(
            state, sort_keys=True, separators=(",", ":"), ensure_ascii=False
        ).encode("utf-8")
        + b"\n"
    )
    with open(args.out, "wb") as f:
        f.write(payload)
        f.flush()
        os.fsync(f.fileno())
    sys.stderr.write(f"snapshot ok: wrote {args.out}\n")
    sys.stderr.flush()
    return EXIT_OK


def _do_apply(args: argparse.Namespace) -> int:
    ops = _parse_batch(args.batch)
    led = Ledger(args.path)
    led.apply_batch(ops)
    sys.stderr.write(f"apply ok: committed {len(ops)} operations\n")
    sys.stderr.flush()
    return EXIT_OK


def _do_repair_tail(args: argparse.Namespace) -> int:
    led = Ledger(args.path)
    result = led.repair_tail()
    if result["verdict"]["ok"]:
        if result["repaired"]:
            sys.stderr.write("repair-tail ok: removed truncated final line\n")
        else:
            sys.stderr.write("repair-tail ok: chain clean\n")
        sys.stderr.flush()
        return EXIT_OK
    return EXIT_CORRUPTION


def main(argv: Sequence[str] | None = None) -> int:
    parser = _build_parser()
    if argv is None:
        argv = sys.argv[1:]
    try:
        args = parser.parse_args(list(argv))
    except SystemExit as exc:
        code = exc.code
        if isinstance(code, int):
            return EXIT_USAGE if code != 0 else EXIT_OK
        return EXIT_USAGE

    try:
        if args.cmd == "verify":
            return _do_verify(args)
        if args.cmd == "snapshot":
            return _do_snapshot(args)
        if args.cmd == "apply":
            return _do_apply(args)
        if args.cmd == "repair-tail":
            return _do_repair_tail(args)
    except ConflictError:
        return EXIT_CONFLICT
    except FileNotFoundError:
        return EXIT_IO
    except OSError:
        return EXIT_IO
    except (ValueError, TypeError, KeyError):
        return EXIT_USAGE

    return EXIT_USAGE

